void A5NLO(int j1, int j2, int j3, int j4, int j5, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb, std::complex<double>& A5LOm, std::complex<double>& A5NLOm, std::complex<double>& A5ax) {

  double s125, mt2;

  auto zab2 = [&za, &zb](int i1, int i2, int i3, int i4) { 
      return za(i1,i2)*zb(i2,i4) + za(i1,i3)*zb(i3,i4); 
  };

  A5ax = czip;
  s125 = s(j1,j2) + s(j1,j5) + s(j2,j5);

  A5LOm = -zb(j1,j4) * zab2(j3,j2,j5,j1) / (zb(j2,j5) * zb(j5,j1) * s125);
  A5NLOm = A51(j2,j5,j1,j4,j3,zb,za) + A52(j2,j1,j5,j4,j3,zb,za) / xnsq;

  if (kcase == kZ_1jet) {
    mt2 = std::pow(mt, 2);
    A5ax = A53(j2,j1,j5,j4,j3,zb,za,mt2) / xn;
  }

  return;
}

extern "C" {
  void A5NLO_wrapper(int j1, int j2, int j3, int j4, int j5, std::complex<double>* fza, std::complex<double>* fzb, std::complex<double>& A5LOm, std::complex<double>& A5NLOm, std::complex<double>& A5ax) {

    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
    A5NLO(j1, j2, j3, j4, j5, za, zb, A5LOm, A5NLOm, A5ax);

  }
}
